while (p + wh <= end) {
  header_t hd = p[0];
  if (POOL_BLOCK_FREE_HD(hd)) {
    p += wh * Wosize_hd(hd);
  } else if (Has_status_hd(hd, caml_global_heap_state.MARKED)) {
    f(fdata, Val_hp(p), 0);
  }
  p += wh;
}

